// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    MockToken sGlp;
    MockToken usdc;
    MockToken depositTokenMock;
    MockGlpManager glpManager;
    MockVault gmxVault;
    MockRewardRouter router;
    MockJuniorVault jv;

    function setUp() public {
        c = new DnGmxBatchingManager();
        sGlp = new MockToken();
        usdc = new MockToken();
        depositTokenMock = new MockToken();
        glpManager = new MockGlpManager();
        gmxVault = new MockVault();
        router = new MockRewardRouter();
        jv = new MockJuniorVault();
        glpManager.setVault(address(gmxVault));
        c.initialize(IERC20(address(sGlp)), IERC20(address(usdc)), IRewardRouterV2(address(router)), IGlpManager(address(glpManager)), address(jv), address(this));
    }

    function testFuzz_property(uint256 amount, uint256 minUSDG, address keeper, uint256 warpTime) public {
        vm.assume(keeper != address(0));
        amount = bound(amount, 1, type(uint128).max);
        c.setKeeper(keeper);
        vm.warp(bound(warpTime, 901, type(uint256).max / 2));

        // fund the batching balance via depositToken from the junior vault itself
        vm.prank(address(jv));
        c.depositToken(address(depositTokenMock), amount, minUSDG);
        assertTrue(c.dnGmxJuniorVaultGlpBalance() == amount, "precondition: balance funded");

        vm.prank(keeper);
        c.executeBatchDeposit();

        // General rule: after executeBatchDeposit, the staked-GLP balance transferred
        // to the junior vault is always reset to zero.
        assertTrue(c.dnGmxJuniorVaultGlpBalance() == 0, "stale balance after batch deposit");
    }
}

